using Respira.Doctor.Domain.Enums;
using Respira.ServiceDefaults.Contracts.CQRS;

namespace Respira.Saga.Application.Features.Update.Commands
{
    /// <summary>
    /// Local (never sent over the broker) message produced by the profile update endpoint
    /// that starts the update saga. It carries the new account data, the new profile data
    /// and the path of the avatar the API stored while it waits for the media step.
    /// </summary>
    public record StartUpdateCommand : ICommand
    {
        /// <summary>Identifier generated by the endpoint; becomes the saga id.</summary>
        public Guid SagaId { get; set; }

        /// <summary>Account to update.</summary>
        public Guid AccountId { get; set; }

        /// <summary>Doctor/manager profile to update.</summary>
        public Guid DoctorId { get; set; }

        public string Email { get; set; } = string.Empty;

        public string Phone { get; set; } = string.Empty;

        /// <summary>
        /// Plaintext password, or null to keep the current one. It is only forwarded to
        /// the update account command and is never stored on the saga state, so it never
        /// reaches the saga table.
        /// </summary>
        public string? Password { get; set; }

        public string FirstName { get; set; } = string.Empty;

        public string LastName { get; set; } = string.Empty;

        public List<DegreeType> Degrees { get; set; } = [];

        public AcademicTitle AcademicTitle { get; set; }

        public PositionType Position { get; set; }

        public GenderType Gender { get; set; }

        public string CitizenIdentificationNumber { get; set; } = string.Empty;

        public DateTimeOffset? DateOfBirth { get; set; }

        public string Address { get; set; } = string.Empty;

        /// <summary>Temp file the endpoint wrote the uploaded avatar to.</summary>
        public string? TempAvatarPath { get; set; }
    }
}
